Change(genesis='e30427e699992327267add669c3bc989f6d16525ba6f493121eec7778638e0ce', deps=(), event=Authored(todo='effectclaims', at=datetime(2026, 11, 23, 23, 2, 51, 871858), actor='bmabsout', kind='todo', created=datetime(2026, 11, 23, 0, 0, 0), body="An effect is performed by whoever holds its claim: a lock as an object in the store library, which the store's arbiter admits one of; the outcome composes with the claim, and one executor is the simplest case.", spec=Flat(value=0.55), rationale=('The taps and every other request for an effect are to be local writes;', 'who may perform one must be decided by the store and not by where a', 'request happened to arrive, so that a second device can perform some', 'effects later without a second design.'), category='', waiting_on='', detail="The design is the store library's (its issue 101): a design note first, then stages with generated laws. Here it is what the taps' stage of local writes waits for: a tap is the request, the claim says who performs it, the outcome settles it. The application keeps only the look for an effect, by its token, in the sink's input before an attempt acts.", source=None, subtodos=(), notes=(), note=''))